import { defineCollection, z } from 'astro:content';
import { glob } from 'astro/loaders';

// Blog posts. Legacy Wix posts are JSON files generated by scripts/convert-posts.py
// (do not hand-edit those; edit the harvested source or the script and re-run).
// New posts can be added as JSON files with the same shape.
const posts = defineCollection({
  loader: glob({ pattern: '*.json', base: './src/content/posts' }),
  schema: z.object({
    slug: z.string(),
    title: z.string(),
    description: z.string().default(''),
    published: z.string(),
    updated: z.string().optional(),
    author: z.string().default('Focus Accountancy'),
    topics: z.array(z.string()).default([]),
    tags: z.array(z.string()).default([]),
    image: z.string().nullable().optional(),
    imageAlt: z.string().optional(),
    imageInline: z.boolean().default(false),
    // Optional designed hero: a green band with the cover beside the title and a row of key facts.
    hero: z
      .object({
        stats: z.array(z.object({ value: z.string(), label: z.string() })).max(4).default([]),
      })
      .optional(),
    words: z.number().optional(),
    legacy: z.boolean().default(false),
    html: z.string(),
  }),
});

// News items migrated from news.focusaccountancy.co.uk (syndicated newsfeed), via scripts/convert-news.py.
const news = defineCollection({
  loader: glob({ pattern: '*.json', base: './src/content/news' }),
  schema: z.object({
    slug: z.string(),
    id: z.number(),
    title: z.string(),
    summary: z.string().default(''),
    published: z.string(),
    image: z.string().nullable().optional(),
    words: z.number().optional(),
    html: z.string(),
  }),
});

// New blog posts written in the site editor (/keystatic): Markdown files with frontmatter.
// src/lib/posts.ts merges them with the legacy posts above.
const ymd = z.coerce.date().transform((d) => d.toISOString().slice(0, 10));
const blog = defineCollection({
  loader: glob({ pattern: '*.md', base: './src/content/blog' }),
  schema: z.object({
    title: z.string(),
    description: z.string().default(''),
    draft: z.boolean().default(false),
    published: ymd,
    updated: ymd.nullable().optional(),
    author: z.string().default('Focus Accountancy'),
    topics: z.array(z.string()).default([]),
    image: z.string().nullable().optional(),
  }),
});

// Articles waiting for Barry's yes/no on the review page (docs/content-queue.md). They reach the site
// through allPosts() in src/lib/posts.ts once approved in src/data/review-decisions.json and their
// lineup date (src/data/lineup.json) has arrived.
const queue = defineCollection({
  loader: glob({ pattern: '*.json', base: './src/content/queue' }),
  schema: z.object({
    slug: z.string(),
    title: z.string(),
    description: z.string().default(''),
    author: z.string().default('Focus Accountancy'),
    topics: z.array(z.string()).default([]),
    kind: z.enum(['new', 'update']).default('new'),
    source: z.string().default('Focus SEO team'),
    sourceRef: z.string().default(''),
    written: z.string().default(''),
    why: z.string().default(''),
    keyword: z
      .object({ term: z.string(), volume: z.number().nullable().optional(), note: z.string().default('') })
      .optional(),
    checks: z
      .array(
        z.object({
          status: z.enum(['ok', 'fixed', 'check']),
          claim: z.string(),
          note: z.string().default(''),
          source: z.string().default(''),
        }),
      )
      .default([]),
    // Optional cover and designed hero, same as published posts (src/content/posts).
    image: z.string().nullable().optional(),
    imageAlt: z.string().optional(),
    hero: z
      .object({
        stats: z.array(z.object({ value: z.string(), label: z.string() })).max(4).default([]),
      })
      .optional(),
    words: z.number().optional(),
    html: z.string(),
  }),
});

export const collections = { posts, news, blog, queue };
